def g1(v, G, nm):
    for n, c in G:
        if abs(v - c) < 0.105: return f'{nm} {n}'
    if v < G[0][1]: return f'นอก{nm} {G[0][0]} {G[0][1] - v:.2f}'
    if v > G[-1][1]: return f'นอก{nm} {G[-1][0]} {v - G[-1][1]:.2f}'
    for (a, ca), (b, cb) in zip(G, G[1:]):
        if ca < v < cb: return f'{nm} {a}–{b} ห่าง {a} {v - ca:.2f}'
